{"modifiedFiles":[],"workingNote":"I’m inspecting the protocol implementation and tests to identify the operation model and add recoverFen without changing the required protocol surface."}{"modifiedFiles":[{"path":"src/protocol_adapter.ts","content":"export type WorldStateHandle = Record<string, string>;

export interface WorldProtocol {
  reset(): WorldStateHandle;
  applyOperation(
    state: WorldStateHandle,
    operationDisplayName: string
  ): { success: true; newState: WorldStateHandle } | { success: false; error: string };
  getEntityState(state: WorldStateHandle, entityDisplayName: string): string;
  toAbstractSnapshot(state: WorldStateHandle): Record<string, string>;
}

const initialState: WorldStateHandle = {
  Fen: "pex",
};

export const protocol: WorldProtocol = {
  reset(): WorldStateHandle {
    return { ...initialState };
  },

  applyOperation(
    state: WorldStateHandle,
    operationDisplayName: string
  ):
    | { success: true; newState: WorldStateHandle }
    | { success: false; error: string } {
    if (operationDisplayName === "advanceFen") {
      if (state.Fen !== "pex") {
        return { success: false, error: "Fen can only advance from pex" };
      }
      return { success: true, newState: { ...state, Fen: "dor" } };
    }

    if (operationDisplayName === "recoverFen") {
      if (state.Fen !== "dor") {
        return { success: false, error: "Fen can only recover from dor" };
      }
      return { success: true, newState: { ...state, Fen: "pex" } };
    }

    return { success: false, error: `Unknown operation: ${operationDisplayName}` };
  },

  getEntityState(state: WorldStateHandle, entityDisplayName: string): string {
    return state[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state: WorldStateHandle): Record<string, string> {
    return { ...state };
  },
};
